#include <initializer_list>
#include "ui_renderer.h"
#include "future_factory_presets.h"
#include <memory>
#include <cassert>
#include <cstdio>
using namespace groove;
int main(){auto p=std::make_unique<ProjectState>();make_empty_project(*p);p->tracks[0].instrument=Instrument::Additive;for(unsigned t=0;t<16;++t){auto tr=track_at(*p,0,t);tr.instrument=Instrument::Additive;tr.length=t%2?12:16;for(unsigned i=0;i<tr.length;++i){tr.steps[i].enabled=i%3==0;tr.steps[i].note=uint8_t(36+t+i);tr.steps[i].velocity=100;}}auto e=std::make_unique<Engine>();auto u=std::make_unique<Performance>(*e,*p);auto r=std::make_unique<UiRenderer>();float audio[512]{},cue[512]{},input[512]{};uint64_t now=2000;
 auto draw=[&](){u->animate(now);r->draw(*p,*u);now+=2000;u->animate(now);r->draw(*p,*u);};
 for(unsigned theme=0;theme<6;++theme){p->ui.theme=uint8_t(theme);p->ui.motion=0;u->project_loaded();for(unsigned mode=0;mode<19;++mode){u->set_mode(UiMode(mode));draw();char name[80];snprintf(name,sizeof name,"theme%u-%02u",theme,mode);if(theme==0){r->text_clock(now,true);r->invalidate();r->draw(*p,*u);auto before=std::make_unique<UiRenderer>();before->draw(*p,*u);bool assigned=u->knob_label(0)[0]!=0;u->dispatch({ControllerInput::Type::KnobTouch,0,1});assert(u->knob_overlay()==assigned);r->draw(*p,*u);snprintf(name,sizeof name,"overlay-%02u",mode);u->dispatch({ControllerInput::Type::KnobTouch,0,0});now+=1199;u->animate(now);assert(u->knob_overlay()==assigned);now+=1;u->animate(now);assert(!u->knob_overlay());r->draw(*p,*u);before->invalidate();before->draw(*p,*u);if(__builtin_memcmp(r->pixels,before->pixels,sizeof r->pixels))std::fprintf(stderr,"Overlay restoration mismatch mode %u theme %u time %llu\n",mode,theme,(unsigned long long)now);assert(!__builtin_memcmp(r->pixels,before->pixels,sizeof r->pixels));}}}
 p->ui.theme=0;u->project_loaded();u->set_mode(UiMode::Step);u->set_shift(true);u->soft_key(3);u->soft_key(3);u->set_shift(false);draw();assert(u->tracker_view());u->knob(0,1000);assert(u->knob_overlay());e->render(audio,0);r->draw(*p,*u);draw();assert(!u->knob_overlay());
 for(unsigned page=0;page<7;++page){u->set_mode(UiMode::Settings);while(u->settings_page()>page)u->encoder_direction(0x20);while(u->settings_page()<page)u->encoder_direction(0x08);assert(u->soft_enabled(page%3));u->storage_space(true,8ull<<30,32ull<<30);if(page==4){for(unsigned n=0;n<160;++n){for(unsigned i=0;i<256;++i){input[2*i]=.2f*sinf(6.283185307f*440*(n*256+i)/48000);input[2*i+1]=input[2*i]*.5f;}e->render_ports(audio,cue,input,256);u->poll();}}draw();char name[64];snprintf(name,sizeof name,"settings-%u",page);u->dispatch({ControllerInput::Type::KnobTouch,0,1});r->draw(*p,*u);snprintf(name,sizeof name,"settings-%u-overlay",page);u->dispatch({ControllerInput::Type::KnobTouch,0,0});}
 u->set_mode(UiMode::Settings);while(u->settings_page()<6)u->encoder_direction(0x08);draw();u->storage_space(true,4ull<<30,32ull<<30);r->draw(*p,*u);auto fresh=std::make_unique<UiRenderer>();fresh->draw(*p,*u);assert(!__builtin_memcmp(r->pixels,fresh->pixels,sizeof r->pixels));
 for(unsigned index: {11u,13u,15u}){make_future_factory_preset(*p,index);assert(e->stage_project(*p));e->render(audio,0);u->project_loaded();u->set_mode(UiMode::Synth);assert(u->pad(12,0x10,3000));for(unsigned n=0;n<40;++n){e->render(audio,256);u->poll();}draw();char name[64];snprintf(name,sizeof name,"engine-%u",index);u->dispatch({ControllerInput::Type::KnobTouch,0,1});r->draw(*p,*u);snprintf(name,sizeof name,"engine-%u-overlay",index);u->dispatch({ControllerInput::Type::KnobTouch,0,0});u->pad(12,0x20,0);}
 printf("Wave4 UI: all 19 pages / six themes, touch/release expiry and clean overlay restore passed\n");}
